-- ===== Upgrade placeholder post #1 =====
UPDATE `blogs` SET
  title = 'Top 10 Tips to Pass Your Canadian Citizenship Test',
  short_description = 'Ten practical, proven tips to help you study smarter and pass the Canadian citizenship test on your first try.',
  content = '<p>Preparing for the Canadian citizenship test does not have to be stressful. With the right plan, most people pass on their first attempt. Here are ten practical tips to pass your Canadian citizenship test with confidence.</p><h2>1. Study the official guide first</h2><p>Every question comes from <strong>Discover Canada</strong>, the official study guide. Read it cover to cover before anything else.</p><h2>2. Practice with realistic mock exams</h2><p>Taking timed practice tests is the fastest way to find your weak spots. Simulate the real 30-minute, 20-question format.</p><h2>3. Focus on rights and responsibilities</h2><p>Questions about the rights and responsibilities of citizenship come up often. Know them well.</p><h2>4. Learn key dates and events</h2><p>Confederation in 1867, the World Wars, and major milestones in Canadian history are common topics.</p><h2>5. Know your government</h2><p>Understand the roles of the monarch, the Governor General, the Prime Minister, and your Member of Parliament.</p><h2>6. Study a little every day</h2><p>Short, daily sessions beat last-minute cramming. Aim for 20 to 30 minutes a day.</p><h2>7. Use your province information</h2><p>Some questions relate to where you live, including your provincial capital and representatives.</p><h2>8. Review questions you get wrong</h2><p>Keep a list of mistakes and revisit them until they stick.</p><h2>9. Stay calm on test day</h2><p>You need 15 out of 20 to pass. Read each question carefully and do not rush.</p><h2>10. Practice in your preferred language</h2><p>If English or French is not your first language, study key terms in your own language first to build understanding.</p><p>Ready to practice? Try a free mock exam and track your progress as you study.</p>',
  updated_at = CURRENT_TIMESTAMP
WHERE id = 1;

-- ===== Upgrade placeholder post #2 =====
UPDATE `blogs` SET
  title = 'How to Study Discover Canada Effectively',
  short_description = 'A step-by-step guide to studying the official Discover Canada guide so you remember more and pass the citizenship test.',
  content = '<p><strong>Discover Canada</strong> is the official study guide for the Canadian citizenship test, and every exam question is based on it. Learning how to study Discover Canada effectively is the single most important thing you can do to pass.</p><h2>Start with the big picture</h2><p>Skim the whole guide once to see how it is organized: rights and responsibilities, history, government, geography, symbols, and the economy. This helps the details make sense later.</p><h2>Break it into chapters</h2><p>Study one section at a time instead of trying to absorb everything at once. After each section, test yourself before moving on.</p><h2>Turn facts into questions</h2><p>As you read, ask yourself: who, what, when, and why. The test rewards understanding, not just memorization.</p><h2>Pay attention to the heavy-hitting topics</h2><ul><li>The rights and responsibilities of citizenship</li><li>Key events in Canadian history</li><li>How the federal government works</li><li>National symbols and important figures</li></ul><h2>Practice, then re-read</h2><p>Take a practice test after studying. Whatever you get wrong, go back to that part of Discover Canada and read it again. This loop is far more effective than reading alone.</p><p>Use a structured study tool to move through every chapter and quiz yourself as you go.</p>',
  updated_at = CURRENT_TIMESTAMP
WHERE id = 2;

-- ===== Upgrade placeholder post #3 =====
UPDATE `blogs` SET
  title = 'From Permanent Resident to Citizen: What the Journey Looks Like',
  short_description = 'A realistic look at the path from permanent residency to Canadian citizenship, including the knowledge test step.',
  content = '<p>Becoming a Canadian citizen is a milestone worth celebrating. While every journey is different, the path from permanent resident to citizen follows a familiar set of steps.</p><h2>Meet the eligibility requirements</h2><p>You generally need to have been a permanent resident and physically present in Canada for a required number of days, along with meeting tax and language requirements. Always confirm the current rules on canada.ca.</p><h2>Submit your application</h2><p>Once eligible, you submit your citizenship application with the supporting documents.</p><h2>Prepare for the citizenship test</h2><p>If you are between the required ages, you will take the citizenship knowledge test. This is where good preparation pays off. Study Discover Canada and take practice exams until you are consistently scoring above the pass mark.</p><h2>Attend the ceremony</h2><p>After passing, the final step is the citizenship ceremony, where you take the Oath of Citizenship and officially become Canadian.</p><p>The knowledge test is the part you can fully control through preparation. Start studying early and practice often.</p>',
  updated_at = CURRENT_TIMESTAMP
WHERE id = 3;

-- ===== New post: how hard is the test =====
INSERT INTO `blogs` (title, slug, short_description, content, status)
VALUES (
  'How Hard Is the Canadian Citizenship Test? A 2026 Guide',
  'how-hard-is-the-canadian-citizenship-test',
  'Wondering how hard the Canadian citizenship test really is? Here is what to expect, the pass mark, and how to make it easy.',
  '<p>If you are asking <strong>how hard is the Canadian citizenship test</strong>, the honest answer is: it is very manageable with preparation. Most people who study pass on their first try. Here is exactly what to expect.</p><h2>What the test looks like</h2><p>The Canadian citizenship test has <strong>20 questions</strong>, is multiple choice and true or false, and you have <strong>45 minutes</strong> to finish. The questions are based entirely on the official Discover Canada guide.</p><h2>What score do you need to pass?</h2><p>You need to answer at least <strong>15 out of 20 questions correctly</strong> &mdash; a 75 percent pass mark. That means you can get up to five questions wrong and still pass.</p><h2>So is it actually hard?</h2><p>The difficulty depends almost entirely on preparation. People who read Discover Canada and take practice tests usually find the real test straightforward. People who do not study often struggle, because some questions cover specific dates, names, and responsibilities.</p><h2>The topics that trip people up</h2><ul><li>Specific dates in Canadian history</li><li>The roles of government officials</li><li>The rights and responsibilities of citizenship</li><li>Provincial and territorial capitals</li></ul><h2>How to make it easy</h2><p>Study a little each day, take timed mock exams, and review every question you get wrong. Aim to score 18 or higher on practice tests before your real exam, so you have a comfortable margin.</p><p>Start with a free practice test to see where you stand today.</p>',
  'active'
)
ON CONFLICT(slug) DO UPDATE SET
  title = excluded.title,
  short_description = excluded.short_description,
  content = excluded.content,
  updated_at = CURRENT_TIMESTAMP;

-- ===== New post: how many questions =====
INSERT INTO `blogs` (title, slug, short_description, content, status)
VALUES (
  'How Many Questions Are on the Canadian Citizenship Test?',
  'how-many-questions-canadian-citizenship-test',
  'The Canadian citizenship test has 20 questions and you need 15 to pass. Here is the full format, timing, and pass mark explained.',
  '<p>One of the most common questions from applicants is <strong>how many questions are on the Canadian citizenship test</strong>. The answer is simple, and knowing the full format helps you prepare with confidence.</p><h2>The short answer</h2><p>The Canadian citizenship test has <strong>20 questions</strong>. You need to answer <strong>15 correctly</strong> to pass, which is 75 percent.</p><h2>The full format at a glance</h2><ul><li><strong>Number of questions:</strong> 20</li><li><strong>Question types:</strong> multiple choice and true or false</li><li><strong>Time limit:</strong> 45 minutes</li><li><strong>Pass mark:</strong> 15 out of 20 (75 percent)</li><li><strong>Source material:</strong> the Discover Canada guide</li></ul><h2>What the questions cover</h2><p>Questions are drawn from across Discover Canada, including the rights and responsibilities of citizenship, Canadian history, geography, the system of government, and national symbols.</p><h2>How much time per question?</h2><p>With 45 minutes for 20 questions, you have more than two minutes each &mdash; plenty of time if you have studied. Most well-prepared applicants finish with time to spare.</p><h2>The best way to prepare</h2><p>Practice with mock exams that match the real 20-question, 30-minute format. This builds both your knowledge and your timing so there are no surprises on test day.</p>',
  'active'
)
ON CONFLICT(slug) DO UPDATE SET
  title = excluded.title,
  short_description = excluded.short_description,
  content = excluded.content,
  updated_at = CURRENT_TIMESTAMP;

-- ===== New post: what to study =====
INSERT INTO `blogs` (title, slug, short_description, content, status)
VALUES (
  'What to Study for the Canadian Citizenship Test: 2026 Checklist',
  'what-to-study-canadian-citizenship-test',
  'A complete checklist of what to study for the Canadian citizenship test, organized by topic so nothing slips through the cracks.',
  '<p>Knowing <strong>what to study for the Canadian citizenship test</strong> saves you time and stress. Everything on the test comes from the Discover Canada guide, so use this checklist to make sure you cover every key area.</p><h2>1. Rights and responsibilities</h2><p>Understand the rights of Canadian citizens and the responsibilities that come with citizenship. This is one of the most heavily tested topics.</p><h2>2. Canadian history</h2><p>Focus on key milestones: the Indigenous peoples, early settlement, Confederation in 1867, the World Wars, and Canada in the modern era.</p><h2>3. How government works</h2><p>Learn the three levels of government, the roles of the monarch, Governor General, Prime Minister, and Members of Parliament, and how laws are made.</p><h2>4. Voting and elections</h2><p>Know how federal elections work and the responsibilities of voters.</p><h2>5. Geography</h2><p>Study the provinces and territories, their capitals, and the major regions of Canada.</p><h2>6. National symbols and identity</h2><p>Be familiar with the flag, the anthem, important national symbols, and notable Canadians.</p><h2>7. Your province or territory</h2><p>Some questions relate to where you live, including local representatives and your provincial capital.</p><h2>Put it all together</h2><p>Once you have covered each topic, take full-length practice tests to confirm you are ready. Review any topic where you score low and test again until you are consistently passing.</p>',
  'active'
)
ON CONFLICT(slug) DO UPDATE SET
  title = excluded.title,
  short_description = excluded.short_description,
  content = excluded.content,
  updated_at = CURRENT_TIMESTAMP;

-- ===== New post: how to prepare in 2026 (author-supplied) =====
INSERT INTO `blogs` (title, slug, short_description, content, status)
VALUES (
  'How to Prepare for the Canadian Citizenship Test in 2026',
  'how-to-prepare-canadian-citizenship-test-2026',
  'Learn how to prepare for the Canadian citizenship test in 2026, what topics to study, how many questions are on the test, and how to pass with confidence.',
  '<p>Preparing for the Canadian citizenship test is an important step toward becoming a Canadian citizen. For many applicants, the test can feel stressful at first. You may wonder what questions will be asked, how much you need to study, or whether the test is difficult.</p><p>The good news is that the Canadian citizenship test is based on one official study guide: <strong>Discover Canada: The Rights and Responsibilities of Citizenship</strong>. If you study the guide carefully and practise with test-style questions, you can feel much more confident before your exam.</p><h2>What Is the Canadian Citizenship Test?</h2><p>The Canadian citizenship test checks your knowledge of Canada and the rights and responsibilities of citizenship. According to the Government of Canada, the test is based on information from the official Discover Canada study guide.</p><p>The test includes questions about:</p><ul><li>Canadian history</li><li>Geography</li><li>Government</li><li>Laws</li><li>Economy</li><li>Rights and responsibilities</li><li>Canadian symbols</li></ul><p>The test is available in English or French. It is not designed to test your language skills, but you do need to understand the questions well enough to answer them correctly.</p><h2>How Many Questions Are on the Citizenship Test?</h2><p>The Canadian citizenship test has <strong>20 questions</strong>. The questions are either multiple choice or true or false.</p><p>You have <strong>45 minutes</strong> to complete the test. To pass, you need to answer at least <strong>15 out of 20 questions correctly</strong>, which means you need a score of 75 percent or higher.</p><p>This is why practice is so helpful. When you take practice tests, you become familiar with the question style and learn how to manage your time.</p><h2>What Should You Study First?</h2><p>Start with the official Discover Canada study guide. This is the most important resource because all official citizenship test questions are based on it.</p><p>Instead of trying to memorize the entire guide in one day, divide your study into smaller sections. Focus on one topic at a time, such as Canadian history, government, or rights and responsibilities.</p><p>A simple study plan could look like this:</p><ul><li><strong>Day 1:</strong> Rights and responsibilities of citizenship</li><li><strong>Day 2:</strong> Canadian history</li><li><strong>Day 3:</strong> Government and elections</li><li><strong>Day 4:</strong> Geography and regions</li><li><strong>Day 5:</strong> Symbols, economy, and review</li><li><strong>Day 6:</strong> Practice questions</li><li><strong>Day 7:</strong> Mock test and final review</li></ul><p>Studying in small parts helps you remember more and reduces stress.</p><h2>Use Practice Questions to Test Yourself</h2><p>Reading the guide is important, but practice questions help you check what you actually remember. Many people understand the material while reading, but find it harder to answer questions under time pressure.</p><p>Practice questions can help you:</p><ul><li>Identify weak areas</li><li>Review important facts</li><li>Get used to multiple-choice questions</li><li>Build confidence before the real test</li><li>Improve your speed</li></ul><p>Try taking short quizzes after each topic. Once you finish the full study guide, take full mock tests that include 20 questions, just like the real citizenship test.</p><h2>Focus on Understanding, Not Just Memorizing</h2><p>Some facts do need to be memorized, such as dates, names, and government roles. But the best way to prepare is to understand the meaning behind the information.</p><p>For example, do not only memorize that citizens have the right to vote. Understand why voting matters in a democracy and how elections work in Canada.</p><p>This approach makes it easier to answer questions even when they are written in a different way.</p><h2>Listen to Audio Lessons If Reading Is Difficult</h2><p>If you find it hard to study by reading alone, audio lessons can help. The official Discover Canada guide is available in audio format, and many study apps also include audio-based lessons.</p><p>Listening while reading can improve concentration and help you remember important words. This is especially useful if English or French is not your first language.</p><p>You can listen while commuting, walking, cooking, or taking a short break. Small study sessions can add up quickly.</p><h2>Take Mock Tests Before the Real Exam</h2><p>Before your real citizenship test, take several mock tests. A mock test gives you a realistic idea of your readiness.</p><p>Try to answer 20 questions within 45 minutes. After each mock test, review your wrong answers carefully. Do not just check the correct option. Go back to the study guide and understand why the answer is correct.</p><p>If you are consistently scoring above 15 out of 20, you are moving in the right direction. If your score is lower, spend more time reviewing your weak topics.</p><h2>Common Mistakes to Avoid</h2><p>Many applicants make the same mistakes while preparing for the Canadian citizenship test.</p><p>One common mistake is waiting until the last few days to study. The study guide includes many topics, so it is better to begin early.</p><p>Another mistake is only taking practice tests without reading the official guide. Practice questions are helpful, but the official guide should be your main source.</p><p>Some people also ignore topics they find boring, such as government structure or Canadian history. These topics are important and may appear on the test.</p><h2>Final Tips to Pass the Canadian Citizenship Test</h2><p>To improve your chances of passing, follow these simple tips:</p><ul><li>Study the official Discover Canada guide</li><li>Review one topic at a time</li><li>Take practice questions after each chapter</li><li>Use audio lessons if they help you focus</li><li>Take full mock tests before your exam</li><li>Review your wrong answers</li><li>Sleep well before test day</li></ul><p>The Canadian citizenship test is very manageable when you prepare properly. With the right study plan, regular practice, and a clear understanding of the official guide, you can walk into your test with confidence.</p><p>Becoming a Canadian citizen is a meaningful milestone. The test is one step in that journey, and good preparation can help you pass it successfully.</p><p><strong>Sources:</strong> <a href="https://www.canada.ca/en/immigration-refugees-citizenship/services/canadian-citizenship/test/study.html" target="_blank" rel="noopener noreferrer">Government of Canada &mdash; Study for the citizenship test</a> and <a href="https://www.canada.ca/en/immigration-refugees-citizenship/corporate/publications-manuals/discover-canada.html" target="_blank" rel="noopener noreferrer">Discover Canada study guide</a>.</p>',
  'active'
)
ON CONFLICT(slug) DO UPDATE SET
  title = excluded.title,
  short_description = excluded.short_description,
  content = excluded.content,
  updated_at = CURRENT_TIMESTAMP;
